<?php
namespace ProjectPress\Admin\Manager\ProjectManager;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;
use ProjectPress\Includes\Project\Core\ProjectFieldRepository;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Fields { private ProjectFieldRepository $repository; public function __construct() { $this->repository = new ProjectFieldRepository(); }
	public function render(): void { $fields = $this->repository->all(); $types = array( 'text', 'textarea', 'integer', 'decimal', 'boolean', 'date', 'datetime', 'select', 'multi_select', 'user', 'url', 'email' ); ?><div class="row g-4"><div class="col-lg-5"><div class="card card-body"><h2 class="h4"><?php esc_html_e( 'Create Global Field', 'projectpress' ); ?></h2><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="projectpress_field_save"/><?php wp_nonce_field( 'projectpress_field_save' ); ?><label class="form-label" for="field-name"><?php esc_html_e( 'Name', 'projectpress' ); ?></label><input class="form-control" id="field-name" name="name" required/><label class="form-label mt-3" for="field-type"><?php esc_html_e( 'Type', 'projectpress' ); ?></label><select class="form-select" id="field-type" name="type"><?php foreach ( $types as $type ) : ?><option value="<?php echo esc_attr( $type ); ?>"><?php echo esc_html( ucwords( str_replace( '_', ' ', $type ) ) ); ?></option><?php endforeach; ?></select><div class="form-check mt-3"><input class="form-check-input" id="field-enabled" name="enabled" value="1" type="checkbox" checked/><label class="form-check-label" for="field-enabled"><?php esc_html_e( 'Enabled', 'projectpress' ); ?></label></div><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e( 'Create Field', 'projectpress' ); ?></button></form></div></div><div class="col-lg-7"><div class="card card-body"><h2 class="h4"><?php esc_html_e( 'Global Fields', 'projectpress' ); ?></h2><?php foreach ( $fields as $field ) : ?><div class="border-bottom py-2 d-flex justify-content-between"><strong><?php echo esc_html( $field['field_name'] ); ?></strong><code><?php echo esc_html( $field['field_type'] ); ?></code></div><?php endforeach; if ( empty( $fields ) ) : ?><p><?php esc_html_e( 'No global fields found.', 'projectpress' ); ?></p><?php endif; ?></div></div></div><?php }
	public function handle_save(): void { check_admin_referer( 'projectpress_field_save' ); if ( ! current_user_can( 'manage_options' ) && ! current_user_can( 'projectpress_fields_manage' ) ) { wp_die( esc_html__( 'You are not authorised to manage fields.', 'projectpress' ) ); } $this->repository->create( array( 'name' => RequestHelper::text( $_POST, 'name', '' ), 'type' => RequestHelper::key( $_POST, 'type', 'text' ), 'enabled' => RequestHelper::boolean( $_POST, 'enabled', false ) ) ); wp_safe_redirect( admin_url( 'admin.php?page=projectpress&group=project-manager&tab=fields' ) ); exit; }
}
